// src/config.ts
var MAP = {
  SIZE: 60,
  /** Width of the ring road along the map edge and of every main road (spec §14.1). */
  ROAD_WIDTH: 4,
  /** Width of a street in a real district. */
  STREET_WIDTH: 3,
  ALLEY_WIDTH: 2,
  /** Rectangles wider or taller than this get split by a main road. */
  BLOCK_MAX: 34,
  /** A split never leaves a block narrower than this. */
  BLOCK_MIN: 12,
  /** Blocks at least this long on one side may get an alley. */
  ALLEY_MIN_BLOCK: 10,
  ALLEY_CHANCE: 0.8,
  /** Buildings inside a block are cut into lots of at most this many cells per side. */
  LOT_MAX: 4,
  FLOORS_MIN: 1,
  FLOORS_MAX: 6
};
var SNAKE = {
  INITIAL_LENGTH: 4,
  /** Cells per second at the initial length. */
  SPEED_BASE: 5,
  SPEED_MAX: 10,
  /** Extra cells per second for every segment beyond the initial length. */
  SPEED_K: 0.05,
  INPUT_QUEUE: 2
};

// src/grid.ts
var Terrain = { BUILDING: 0, ROAD: 1, ALLEY: 2, STREET: 3 };
var DIRS = [0, 1, 2, 3];
var DX = [0, 1, 0, -1];
var DZ = [-1, 0, 1, 0];
var opposite = (dir) => (dir + 2) % 4;
var Grid = class {
  constructor(width2, height2) {
    this.width = width2;
    this.height = height2;
    this.cellCount = width2 * height2;
    this.terrain = new Uint8Array(this.cellCount);
  }
  cellCount;
  terrain;
  index(x, z) {
    return z * this.width + x;
  }
  x(cell) {
    return cell % this.width;
  }
  z(cell) {
    return Math.floor(cell / this.width);
  }
  inside(x, z) {
    return x >= 0 && z >= 0 && x < this.width && z < this.height;
  }
  walkable(cell) {
    return this.terrain[cell] !== Terrain.BUILDING;
  }
  /** The cell one step away, or −1 past the map edge. */
  neighbor(cell, dir) {
    const x = this.x(cell) + DX[dir];
    const z = this.z(cell) + DZ[dir];
    return this.inside(x, z) ? this.index(x, z) : -1;
  }
  /** Direction from `from` to the adjacent cell `to`. */
  dirTo(from, to) {
    const dx = this.x(to) - this.x(from);
    const dz = this.z(to) - this.z(from);
    if (dx > 0) return 1;
    if (dx < 0) return 3;
    return dz > 0 ? 2 : 0;
  }
  /** Steps from the map edge, so 0 on the outermost ring. */
  edgeDistance(cell) {
    const x = this.x(cell);
    const z = this.z(cell);
    return Math.min(x, z, this.width - 1 - x, this.height - 1 - z);
  }
  /**
   * Breadth-first step counts from `sources` over walkable cells, skipping cells where
   * `blocked` is true. Unreached cells are −1. Sources are always distance 0.
   */
  distances(sources, blocked, out) {
    out.fill(-1);
    const queue = new Int32Array(this.cellCount);
    let head = 0;
    let tail = 0;
    for (const source of sources) {
      out[source] = 0;
      queue[tail++] = source;
    }
    while (head < tail) {
      const cell = queue[head++];
      for (const dir of DIRS) {
        const next = this.neighbor(cell, dir);
        if (next < 0 || out[next] >= 0 || !this.walkable(next) || blocked(next)) continue;
        out[next] = out[cell] + 1;
        queue[tail++] = next;
      }
    }
    return out;
  }
};

// src/map/city.ts
var BUILDING_COLORS = 8;
function finishCity(id, grid, lots, alleys) {
  const entry = [];
  for (let cell = 0; cell < grid.cellCount; cell++) {
    if (grid.terrain[cell] === Terrain.ROAD && grid.edgeDistance(cell) < MAP.ROAD_WIDTH) entry.push(cell);
  }
  return { id, grid, lots, alleys, spawn: findSpawn(grid), entry };
}
function straightRun(grid, cell, dir) {
  let run = 0;
  for (let next = grid.neighbor(cell, dir); next >= 0 && grid.walkable(next); next = grid.neighbor(next, dir)) run++;
  return run;
}
function findSpawn(grid) {
  const centreX = (grid.width - 1) / 2;
  const centreZ = (grid.height - 1) / 2;
  const candidates = [];
  for (let cell = 0; cell < grid.cellCount; cell++) {
    if (grid.terrain[cell] === Terrain.ROAD) candidates.push(cell);
  }
  const offset = (cell) => Math.abs(grid.x(cell) - centreX) + Math.abs(grid.z(cell) - centreZ);
  candidates.sort((a, b) => offset(a) - offset(b));
  for (const cell of candidates) {
    let best = null;
    let bestRun = 0;
    for (const dir of [0, 1, 2, 3]) {
      const behind = (dir + 2) % 4;
      if (straightRun(grid, cell, behind) < SNAKE.INITIAL_LENGTH - 1) continue;
      const run = straightRun(grid, cell, dir);
      if (run > bestRun) {
        best = { cell, dir };
        bestRun = run;
      }
    }
    if (best && bestRun >= 3) return best;
  }
  throw new Error("No road cell can hold the initial snake.");
}

